-- G3: somente leitura, executar como postgres após 013. Zero linhas = sem divergências nestes checks.
WITH entry AS (
 SELECT p.*,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname IN ('iasdpi_session_allowed','iasdpi_identity_state_save','iasdpi_department_access_save','iasdpi_governance_catalog','iasdpi_governance_history','iasdpi_department_members','iasdpi_access_request_options','iasdpi_access_request_submit','iasdpi_access_requests','iasdpi_access_request_review','iasdpi_access_reset_issue','iasdpi_access_reset_claim','iasdpi_access_reset_finish')
), private_tables AS (
 SELECT c.* FROM pg_class c WHERE c.oid IN ('iasdpi_admin_private.identity_states'::regclass,'iasdpi_admin_private.access_requests'::regclass,'iasdpi_admin_private.reset_capabilities'::regclass,'iasdpi_governance_private.identity_epochs'::regclass)
), issues AS (
 SELECT 'missing_rpc' issue,name detail FROM unnest(ARRAY['iasdpi_session_allowed','iasdpi_identity_state_save','iasdpi_department_access_save','iasdpi_governance_catalog','iasdpi_governance_history','iasdpi_department_members','iasdpi_access_request_options','iasdpi_access_request_submit','iasdpi_access_requests','iasdpi_access_request_review','iasdpi_access_reset_issue','iasdpi_access_reset_claim','iasdpi_access_reset_finish']) name WHERE NOT EXISTS(SELECT 1 FROM entry WHERE proname=name)
 UNION ALL SELECT 'function_security',oid::regprocedure::text FROM entry WHERE NOT prosecdef OR proowner<>'iasdpi_church_executor'::regrole OR NOT coalesce('search_path=""'=ANY(proconfig),false)
 UNION ALL SELECT 'service_only',oid::regprocedure::text FROM entry WHERE proname IN('iasdpi_access_request_submit','iasdpi_access_reset_claim','iasdpi_access_reset_finish') AND (has_function_privilege('anon',oid,'execute') OR has_function_privilege('authenticated',oid,'execute') OR NOT has_function_privilege('service_role',oid,'execute'))
 UNION ALL SELECT 'authenticated_only',oid::regprocedure::text FROM entry WHERE proname NOT IN('iasdpi_access_request_options','iasdpi_access_request_submit','iasdpi_access_reset_claim','iasdpi_access_reset_finish') AND (has_function_privilege('anon',oid,'execute') OR NOT has_function_privilege('authenticated',oid,'execute'))
 UNION ALL SELECT 'private_table',oid::regclass::text FROM private_tables WHERE NOT relrowsecurity OR relowner<>'postgres'::regrole OR has_table_privilege('anon',oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',oid,'SELECT,INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'private_schema',n.nspname FROM pg_namespace n WHERE n.nspname IN('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private','iasdpi_governance_private') AND (has_schema_privilege('anon',n.oid,'usage,create') OR has_schema_privilege('authenticated',n.oid,'usage,create'))
 UNION ALL SELECT 'private_execute',p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private','iasdpi_governance_private') AND (has_function_privilege('anon',p.oid,'execute') OR has_function_privilege('authenticated',p.oid,'execute'))
 UNION ALL SELECT 'rest_session_policy',name FROM unnest(ARRAY['iasdpi_access','iasdpi_templates','culto_archives','iasdpi_programs','iasdpi_activities','iasdpi_subactivities']) name WHERE NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=('public.'||name)::regclass AND polname='governance_session' AND NOT polpermissive AND polroles=ARRAY['authenticated'::regrole::oid])
 UNION ALL SELECT 'capability_without_view',id::text FROM public.schedule_department_access WHERE (can_edit OR can_publish OR can_manage_members OR can_manage_access OR can_handle_requests) AND NOT can_view
 UNION ALL SELECT 'status_inconsistent',id::text FROM public.schedule_department_access WHERE enabled IS DISTINCT FROM (status='active')
 UNION ALL SELECT 'missing_active_admin',c.code FROM public.iasdpi_churches c WHERE c.active AND c.code='IASD_PI' AND NOT EXISTS(SELECT 1 FROM public.iasdpi_access a WHERE a.church_id=c.id AND a.enabled AND a.role='admin' AND NOT EXISTS(SELECT 1 FROM iasdpi_admin_private.identity_states s WHERE s.church_id=c.id AND s.user_id=a.user_id AND s.status<>'active') AND NOT EXISTS(SELECT 1 FROM iasdpi_governance_private.identity_epochs e WHERE e.user_id=a.user_id AND e.blocked))
) SELECT issue,detail FROM issues ORDER BY issue,detail;
